-- =====================================================================
-- Brixx Hub — 0026: los videos "para nosotros" de Nexa y Alcione
-- Los dos planes de implementación que armamos a mano (mismo formato que
-- los que hace la función "videos") quedan en la carpeta de cada cliente
-- con enfoque "interno". Sus voces están en public/material/planes/ (el
-- reproductor las baja de ahí porque la ruta empieza con "/").
-- Si el cliente no tiene carpeta, no hace nada. Idempotente (uno por cliente).
-- =====================================================================

do $$
declare
  pid uuid;
begin

  -- Nexa Gestión Humana
  select id into pid from public.prospectos
  where public.nombre_comparable(coalesce(empresa, '')) like '%nexagestionhumana%' or public.nombre_comparable(nombre) like '%nexagestionhumana%'
  order by created_at limit 1;
