    values (pid, 'Plan para Alcione Deco: setter con IA en WhatsApp', 'interno', 'listo', $g${"titulo": "Plan para Alcione Deco: setter con IA en WhatsApp", "cliente": "Alcione Deco", "etiqueta": "Plan de implementación", "escenas": [{"tipo": "apertura", "vista": "cliente_final", "seccion": null, "narracion": "Este es el plan para Alcione Deco. Vamos a armarle un setter con inteligencia artificial en WhatsApp que atienda, venda y haga el seguimiento de su web nueva, sin que el equipo conteste precios todo el día.", "titulo": "Setter con IA para la web nueva", "subtitulo": "Para que ninguna consulta se pierda y el equipo atienda solo lo que necesita una persona", "contacto": null, "mensajes": [], "por_dentro": [], "items": [], "columnas": [], "cambios": []}, {"tipo": "panel", "vista": "cliente_final", "seccion": "Qué le vendemos", "narracion": "Le proponemos el bot de WhatsApp con inteligencia artificial conectado a la tienda, las automatizaciones de seguimiento, y un panel con las ventas, las consultas y los envíos.", "titulo": "La propuesta", "subtitulo": null, "contacto": null, "mensajes": [], "por_dentro": [], "items": [{"titulo": "Bot de WhatsApp con IA", "detalle": "Atiende, sugiere productos, manda el link de pago y deriva · precio del catálogo"}, {"titulo": "Automatizaciones", "detalle": "Carritos abandonados, avisos de stock y seguimiento de envíos · a cotizar"}, {"titulo": "Panel y CRM", "detalle": "Ventas del día, clientas, envíos y retiros · a cotizar"}], "columnas": [], "cambios": []}, {"tipo": "flujo", "vista": "cliente_final", "seccion": null, "narracion": "Lo armamos con la API oficial de WhatsApp conectada a Claude, leyendo el catálogo y el stock de su tienda online, con los links de Mercado Pago, y las clientas y ventas guardadas en Supabase.", "titulo": "Cómo lo armamos", "subtitulo": null, "contacto": null, "mensajes": [], "por_dentro": [], "items": [{"titulo": "WhatsApp Cloud API", "detalle": "El número de Alcione"}, {"titulo": "Claude", "detalle": "Conversa y vende"}, {"titulo": "Tienda online", "detalle": "Catálogo, precios y stock"}, {"titulo": "Mercado Pago", "detalle": "Links de pago en cuotas"}, {"titulo": "Supabase y panel", "detalle": "Clientas, ventas y envíos"}], "columnas": [], "cambios": []}, {"tipo": "pasos", "vista": "cliente_final", "seccion": "Paso a paso", "narracion": "Paso a paso: primero relevamos su tienda, cómo hacen los envíos y cómo hablan con las clientas. Después conectamos el catálogo y el stock, armamos el bot base con sus reglas, sumamos pagos y seguimientos, probamos con el equipo, y lo abrimos al público con la web.", "titulo": "De la tienda al lanzamiento", "subtitulo": null, "contacto": null, "mensajes": [], "por_dentro": [], "items": [{"titulo": "Semana 1 · Relevamiento", "detalle": "Qué plataforma usa la web, envíos, cuotas, y chats reales para copiar el tono"}, {"titulo": "Semana 2 · Catálogo y stock", "detalle": "Conectar productos, precios y stock de la tienda, sin cargar nada a mano"}, {"titulo": "Semana 3 · Bot base", "detalle": "Responder, sugerir productos y las reglas: no inventa precios ni da descuentos"}, {"titulo": "Semana 4 · Pagos y seguimiento", "detalle": "Links de Mercado Pago, avisos de envío y carritos abandonados"}, {"titulo": "Semana 5 · Prueba con el equipo", "detalle": "Caro y el equipo lo prueban y ajustamos derivaciones y tono"}, {"titulo": "Semana 6 · Lanzamiento", "detalle": "Lo abrimos junto con la web nueva y activamos el panel"}], "columnas": [], "cambios": []}, {"tipo": "panel", "vista": "cliente_final", "seccion": "Qué le pedimos", "narracion": "Le pedimos el acceso a la tienda online, el número de WhatsApp del local, su cuenta de Mercado Pago, las reglas de envío y cuotas, y algunos chats reales para que el bot hable como ellos.", "titulo": "Lo que necesitamos de Alcione", "subtitulo": null, "contacto": null, "mensajes": [], "por_dentro": [], "items": [{"titulo": "Acceso a la tienda online", "detalle": "Para leer catálogo, precios y stock"},